def is_magic(seq):
    n = len(seq)
    for i in range(n):
        if seq.count(i) != seq[i]:
            return False
    return True

def find_solutions(n=16):
    solutions = []

    def search(i, remaining_sum, current):
        if i == 1:
            if remaining_sum >= 0 and remaining_sum <= n:
                current[1] = remaining_sum
                x0 = sum((k-1) * current[k] for k in range(2, n))
                if x0 >= 0 and x0 <= n:
                    current[0] = x0
                    if sum(current) == n:
                        if is_magic(current):
                            solutions.append(current.copy())
            return

        max_val = min(n, remaining_sum // i) if i > 0 else n
        for val in range(max_val + 1):
            current[i] = val
            search(i - 1, remaining_sum - i * val, current)

    current = [0] * n
    search(15, 16, current)
    return solutions

sols = find_solutions(16)
print(f"Found {len(sols)} magic sequences:")
for sol in sols:
    print(sol)
    # Verify
    for i in range(16):
        assert sol.count(i) == sol[i], f"Failed at i={i}: count={sol.count(i)}, x[i]={sol[i]}"
    print("Verified!")
